<?php
require_once __DIR__ . '/config/bootstrap.php';
$rows=$pdo->query('SELECT p.*,c.name category_name,s.name supplier_name FROM products p JOIN categories c ON c.id=p.category_id JOIN suppliers s ON s.id=p.supplier_id ORDER BY p.id')->fetchAll();
$totalValue=0; foreach($rows as $r)$totalValue += $r['price']*$r['stock'];
?><!doctype html><html lang="id"><head><meta charset="utf-8"><title>Laporan Inventaris</title><style>body{font:13px Arial;margin:35px;color:#172033}h1{margin:0 0 4px}p{color:#68738b}table{width:100%;border-collapse:collapse;margin-top:25px}th,td{border:1px solid #ddd;padding:9px;text-align:left}th{background:#f1f3f7}.summary{margin-top:18px;font-weight:700}@media print{button{display:none}}</style></head><body><button onclick="window.print()">Cetak</button><h1>Laporan Inventaris</h1><p>Tugas Rutin 8 — CRUD Inventaris</p><table><thead><tr><th>No</th><th>Produk</th><th>Kategori</th><th>Supplier</th><th>Harga</th><th>Stok</th></tr></thead><tbody><?php foreach($rows as $i=>$r): ?><tr><td><?= $i+1 ?></td><td><?= e($r['name']) ?></td><td><?= e($r['category_name']) ?></td><td><?= e($r['supplier_name']) ?></td><td><?= rupiah($r['price']) ?></td><td><?= $r['stock'] ?></td></tr><?php endforeach; ?></tbody></table><div class="summary">Total nilai inventaris: <?= rupiah($totalValue) ?></div></body></html>
